import sys

def main():
    n = int(sys.stdin.read().split()[0])
    if n % 2 == 0:
        print(0)
        return
    f = {1: [()]}
    for s in range(3, n + 1, 2):
        cur = []
        for a in range(1, s - 1, 2):
            for l in f[a]:
                for r in f[s - 1 - a]:
                    cur.append((l, r))
        f[s] = cur

    def ser(root):
        out = ['0']
        queue = [root]
        h = 0
        while h < len(queue):
            node = queue[h]
            h += 1
            if node == ():
                out.append('null')
                out.append('null')
            else:
                for c in node:
                    out.append('0')
                    queue.append(c)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    res = [ser(t) for t in f[n]]
    print(len(res))
    print('\n'.join(res))

main()

