found = []

def rec(s, need):
    if need == 0:
        if len(s) == n:
            found.append(s)
        return
    if len(s) >= n:
        return
    rec(s + '1', need + 1)
    rec(s + '0', need - 1)

rec('', 1)

def build(s):
    pos = [0]
    def go():
        c = s[pos[0]]
        pos[0] += 1
        if c == '0':
            return None
        left = go()
        right = go()
        return [left, right]
    return go()

def size(t):
    return 1 if t is None else 1 + size(t[0]) + size(t[1])

def key(t):
    if t is None:
        return (0,)
    return (size(t[0]), key(t[0]), key(t[1]))

trees = [build(s) for s in found]
trees.sort(key=key)

def level(t):
    vals = []
    q = [t]
    i = 0
    while i < len(q):
        x = q[i]
        i += 1
        if x == 'N':
            vals.append('null')
            continue
        vals.append('0')
        if x is None:
            q.append('N')
            q.append('N')
        else:
            q.append(x[0])
            q.append(x[1])
    while vals[-1] == 'null':
        vals.pop()
    return ' '.join(vals)

print(len(trees))
for t in trees:
    print(level(t))

